//! Coordinate level geometric predicates, kept free of the node arena so the
//! arithmetic stays a literal transcription of `earcut.hpp`.
//!
//! Every expression below keeps the C++ operand order and association, because
//! floating point addition and multiplication are not associative and the
//! predicates are exact-comparison based (`>= 0`, `== 0`).

/// `std::min<double>(a, b)` — returns `a` unless `b` is strictly smaller.
///
/// Not `f64::min`, which has different NaN/`-0.0` behaviour.
#[inline]
pub fn cpp_min(a: f64, b: f64) -> f64 {
    if b < a {
        b
    } else {
        a
    }
}

/// `std::max<double>(a, b)` — returns `a` unless `b` is strictly greater.
#[inline]
pub fn cpp_max(a: f64, b: f64) -> f64 {
    if a < b {
        b
    } else {
        a
    }
}

/// Signed area of a triangle, `(q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)`.
///
/// Negative for counter-clockwise triangles, which is the winding the algorithm
/// keeps the outer ring in.
#[inline]
pub fn area(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
}

/// `sign(val)` — `(0.0 < val) - (val < 0.0)`.
#[inline]
pub fn sign(val: f64) -> i32 {
    (0.0 < val) as i32 - (val < 0.0) as i32
}

/// Whether point `p` lies inside (or on) triangle `abc`.
#[inline]
#[allow(clippy::too_many_arguments)]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

/// z-order of a point given the bounding box origin and inverse size.
///
/// Coordinates are transformed into a non-negative 15 bit integer range and
/// interleaved (Morton code).
#[inline]
pub fn z_order(x_: f64, y_: f64, min_x: f64, min_y: f64, inv_size: f64) -> i32 {
    // coords are transformed into non-negative 15-bit integer range
    let mut x: i32 = ((x_ - min_x) * inv_size) as i32;
    let mut y: i32 = ((y_ - min_y) * inv_size) as i32;

    x = (x | (x << 8)) & 0x00FF00FF;
    x = (x | (x << 4)) & 0x0F0F0F0F;
    x = (x | (x << 2)) & 0x33333333;
    x = (x | (x << 1)) & 0x55555555;

    y = (y | (y << 8)) & 0x00FF00FF;
    y = (y | (y << 4)) & 0x0F0F0F0F;
    y = (y | (y << 2)) & 0x33333333;
    y = (y | (y << 1)) & 0x55555555;

    x | (y << 1)
}

