//! The ear clipping triangulator itself — a transcription of
//! `mapbox::detail::Earcut<N>` from `earcut.hpp`.
//!
//! The pipeline, in order:
//!
//! 1. `linked_list` turns each ring into a circular doubly linked list, forcing
//!    the outer ring counter-clockwise and holes clockwise.
//! 2. `eliminate_holes` bridges every hole into the outer ring, left to right.
//!    A hole for which no bridge can be found is silently dropped.
//! 3. For polygons above a size threshold the remaining ring is indexed along a
//!    z-order (Morton) curve so that the "is this an ear?" test only has to look
//!    at points whose z value falls inside the candidate triangle's bounding box.
//! 4. `earcut_linked` slices ears off one at a time, escalating through three
//!    recovery passes (filter collinear points, cure local self intersections,
//!    split the polygon along a diagonal) whenever it runs out of ears.
//!
//! Nodes are arena handles rather than raw pointers; see [`super::node`].

use super::geom::{area, cpp_max, cpp_min, point_in_triangle, sign, z_order};
use super::index::IndexType;
use super::node::{NodeArena, NULL};
use super::point::Point2D;

/// Triangulate a polygon given as a sequence of rings.
///
/// The first ring is the outer boundary, the rest are holes. Returns a flat list
/// of vertex indices, three per triangle, indexing into the concatenation of all
/// rings. Mirrors `mapbox::earcut<N>(poly)`.
pub fn earcut<N, P, R>(poly: &[R]) -> Vec<N>
where
    N: IndexType,
    P: Point2D,
    R: AsRef<[P]>,
{
    let mut earcut: Earcut<N> = Earcut::new();
    earcut.run(poly);
    earcut.into_indices()
}

/// Reusable triangulator state. Calling [`Earcut::run`] more than once reuses
/// the node arena, exactly like holding on to a `mapbox::detail::Earcut<N>`.
pub struct Earcut<N: IndexType> {
    /// Flat triangle list produced by the last [`Earcut::run`].
    pub indices: Vec<N>,
    /// Number of vertices consumed so far by `linked_list`.
    vertices: usize,

    nodes: NodeArena,

    hashing: bool,
    min_x: f64,
    min_y: f64,
    max_x: f64,
    max_y: f64,
    inv_size: f64,
}

impl<N: IndexType> Default for Earcut<N> {
    fn default() -> Earcut<N> {
        Earcut::new()
    }
}

impl<N: IndexType> Earcut<N> {
    pub fn new() -> Earcut<N> {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            nodes: NodeArena::new(),
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            max_x: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// Consume the triangulator, yielding the triangle list.
    pub fn into_indices(self) -> Vec<N> {
        self.indices
    }

    /// `void Earcut<N>::operator()(const Polygon& points)`
    pub fn run<P, R>(&mut self, points: &[R])
    where
        P: Point2D,
        R: AsRef<[P]>,
    {
        // reset
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        let mut threshold: i32 = 80;
        let mut len: usize = 0;

        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].as_ref().len() as i32;
            len += points[i].as_ref().len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.nodes.reset(len * 3 / 2);
        self.indices.reserve(len + points[0].as_ref().len());

        let mut outer_node = self.linked_list(points[0].as_ref(), true);
        if outer_node == NULL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.min_x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.min_y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                self.min_x = cpp_min(self.min_x, x);
                self.min_y = cpp_min(self.min_y, y);
                self.max_x = cpp_max(self.max_x, x);
                self.max_y = cpp_max(self.max_y, y);
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and size are later used to transform coords into
            // integers for z-order calculation
            self.inv_size = cpp_max(self.max_x - self.min_x, self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    /// Create a circular doubly linked list from polygon points in the specified
    /// winding order.
    fn linked_list<P: Point2D>(&mut self, points: &[P], clockwise: bool) -> usize {
        let mut sum = 0.0f64;
        let len = points.len();
        let mut last = NULL;

        // calculate original winding order of a polygon ring
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = &points[i];
            let p2 = &points[j];
            let p20 = p2.x();
            let p10 = p1.x();
            let p11 = p1.y();
            let p21 = p2.y();
            sum += (p20 - p10) * (p11 + p21);
            j = i;
        }

        // link points into circular doubly-linked list in the specified winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                let v = self.vertices + i;
                last = self.insert_node(v, points[i].x(), points[i].y(), last);
            }
        } else {
            for i in (0..len).rev() {
                let v = self.vertices + i;
                last = self.insert_node(v, points[i].x(), points[i].y(), last);
            }
        }

        if last != NULL {
            let next = self.nodes[last].next;
            if self.equals(last, next) {
                self.remove_node(last);
                last = self.nodes[last].next;
            }
        }

        self.vertices += len;

        last
    }

    /// Eliminate colinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NULL {
            return NULL;
        }
        let mut end = if end == NULL { start } else { end };

        let mut p = start;
        let mut again;
        loop {
            again = false;

            let next = self.nodes[p].next;
            let prev = self.nodes[p].prev;
            if !self.nodes[p].steiner
                && (self.equals(p, next) || self.area(prev, p, next) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
    fn earcut_linked(&mut self, ear_in: usize, pass: i32) {
        let mut ear = ear_in;
        if ear == NULL {
            return;
        }

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(N::from_usize(self.nodes[prev].i));
                self.indices.push(N::from_usize(self.nodes[ear].i));
                self.indices.push(N::from_usize(self.nodes[next].i));

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                // try filtering points and slicing again
                if pass == 0 {
                    let filtered = self.filter_points(ear, NULL);
                    self.earcut_linked(filtered, 1);
                }
                // if this didn't work, try curing all small self-intersections locally
                else if pass == 1 {
                    let filtered = self.filter_points(ear, NULL);
                    ear = self.cure_local_intersections(filtered);
                    self.earcut_linked(ear, 2);
                }
                // as a last resort, try splitting the remaining polygon into two
                else if pass == 2 {
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != self.nodes[ear].prev {
            if self.point_in_triangle(a, b, c, p)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    /// The z-order accelerated variant of [`Earcut::is_ear`].
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = cpp_min(self.nodes[a].x, cpp_min(self.nodes[b].x, self.nodes[c].x));
        let min_ty = cpp_min(self.nodes[a].y, cpp_min(self.nodes[b].y, self.nodes[c].y));
        let max_tx = cpp_max(self.nodes[a].x, cpp_max(self.nodes[b].x, self.nodes[c].x));
        let max_ty = cpp_max(self.nodes[a].y, cpp_max(self.nodes[b].y, self.nodes[c].y));

        // z-order range for the current triangle bbox;
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;

        while p != NULL && self.nodes[p].z <= max_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && self.point_in_triangle(a, b, c, p)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;

        while p != NULL && self.nodes[p].z >= min_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && self.point_in_triangle(a, b, c, p)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start_in: usize) -> usize {
        let mut start = start_in;
        if start == NULL {
            return NULL;
        }
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let next = self.nodes[p].next;
            let b = self.nodes[next].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(N::from_usize(self.nodes[a].i));
                self.indices.push(N::from_usize(self.nodes[p].i));
                self.indices.push(N::from_usize(self.nodes[b].i));

                // remove two nodes involved
                self.remove_node(p);
                let pn = self.nodes[p].next;
                self.remove_node(pn);

                p = b;
                start = b;
            }

            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NULL)
    }

    /// Try splitting polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let an = self.nodes[a].next;
                    a = self.filter_points(a, an);
                    let cn = self.nodes[c].next;
                    c = self.filter_points(c, cn);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Link every hole into the outer loop, producing a single-ring polygon
    /// without holes.
    fn eliminate_holes<P, R>(&mut self, points: &[R], outer_node_in: usize) -> usize
    where
        P: Point2D,
        R: AsRef<[P]>,
    {
        let mut outer_node = outer_node_in;
        let len = points.len();

        let mut queue: Vec<usize> = Vec::new();
        for i in 1..len {
            let list = self.linked_list(points[i].as_ref(), false);
            if list != NULL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        // `std::sort(queue.begin(), queue.end(), [](a, b) { return a->x < b->x; })`
        let xs: Vec<f64> = queue.iter().map(|&h| self.nodes[h].x).collect();
        let mut order: Vec<usize> = (0..queue.len()).collect();
        order.sort_by(|&l, &r| {
            if xs[l] < xs[r] {
                std::cmp::Ordering::Less
            } else if xs[r] < xs[l] {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        });
        let queue: Vec<usize> = order.into_iter().map(|k| queue[k]).collect();

        // process holes from left to right
        for &hole in queue.iter() {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects a hole with an outer ring
    /// and link it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NULL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let brn = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, brn);
        let bn = self.nodes[bridge].next;
        self.filter_points(bridge, bn)
    }

    /// David Eberly's algorithm for finding a bridge between a hole and an
    /// outer polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NULL;

        // find a segment intersected by a ray from the hole's leftmost vertex to
        // the left; segment's endpoint with lesser x will be potential
        // connection vertex
        loop {
            let next = self.nodes[p].next;
            if hy <= self.nodes[p].y && hy >= self.nodes[next].y && self.nodes[next].y != self.nodes[p].y
            {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y) / (self.nodes[next].y - self.nodes[p].y)
                        * (self.nodes[next].x - self.nodes[p].x);
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.nodes[p].x < self.nodes[next].x {
                        p
                    } else {
                        next
                    };
                    if x == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        if m == NULL {
            return NULL;
        }

        // look for points inside the triangle of hole vertex, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the vertex of the minimum angle
        // with the ray as connection vertex

        let stop = m;
        let mut tan_min = f64::INFINITY;

        p = m;
        let mut mx = self.nodes[m].x;
        let mut my = self.nodes[m].y;

        loop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px); // tangential

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    mx = self.nodes[m].x;
                    my = self.nodes[m].y;
                    tan_min = tan;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }

    /// Whether the sector in vertex `m` contains the sector in vertex `p` in the
    /// same coordinates.
    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes[m].prev, m, self.nodes[p].prev) < 0.0
            && self.area(self.nodes[p].next, m, self.nodes[m].next) < 0.0
    }

    /// Interlink polygon nodes in z-order.
    fn index_curve(&mut self, start: usize) {
        debug_assert!(start != NULL);
        let mut p = start;

        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let pz = self.nodes[p].prev_z;
        self.nodes[pz].next_z = NULL;
        self.nodes[p].prev_z = NULL;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked list merge sort algorithm, sorting by `z`.
    fn sort_linked(&mut self, list_in: usize) -> usize {
        debug_assert!(list_in != NULL);
        let mut list = list_in;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0;
                let mut i = 0;
                while i < in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                    i += 1;
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NULL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    /// Find the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        leftmost
    }

    /// Check if a diagonal between two polygon nodes is valid (lies in polygon
    /// interior).
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let a_next = self.nodes[a].next;
        let a_prev = self.nodes[a].prev;
        let b_prev = self.nodes[b].prev;
        let b_next = self.nodes[b].next;

        // dones't intersect other edges
        self.nodes[a_next].i != self.nodes[b].i
            && self.nodes[a_prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            // locally visible
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                // does not create opposite-facing sectors
                && (self.area(a_prev, a, b_prev) != 0.0 || self.area(a, b_prev, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(a_prev, a, a_next) > 0.0
                    && self.area(b_prev, b, b_next) > 0.0))
    }

    /// Signed area of the triangle formed by three nodes.
    #[inline]
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        area(
            self.nodes[p].x,
            self.nodes[p].y,
            self.nodes[q].x,
            self.nodes[q].y,
            self.nodes[r].x,
            self.nodes[r].y,
        )
    }

    /// Check if two points are equal.
    #[inline]
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    #[inline]
    fn point_in_triangle(&self, a: usize, b: usize, c: usize, p: usize) -> bool {
        point_in_triangle(
            self.nodes[a].x,
            self.nodes[a].y,
            self.nodes[b].x,
            self.nodes[b].y,
            self.nodes[c].x,
            self.nodes[c].y,
            self.nodes[p].x,
            self.nodes[p].y,
        )
    }

    #[inline]
    fn z_order(&self, x: f64, y: f64) -> i32 {
        z_order(x, y, self.min_x, self.min_y, self.inv_size)
    }

    /// Check if two segments intersect.
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        // p1, q1 and p2 are collinear and p2 lies on p1q1
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true;
        }
        // p1, q1 and q2 are collinear and q2 lies on p1q1
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true;
        }
        // p2, q2 and p1 are collinear and p1 lies on p2q2
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true;
        }
        // p2, q2 and q1 are collinear and q1 lies on p2q2
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true;
        }

        false
    }

    /// For collinear points `p`, `q`, `r`, check if point `q` lies on segment `pr`.
    fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        self.nodes[q].x <= cpp_max(self.nodes[p].x, self.nodes[r].x)
            && self.nodes[q].x >= cpp_min(self.nodes[p].x, self.nodes[r].x)
            && self.nodes[q].y <= cpp_max(self.nodes[p].y, self.nodes[r].y)
            && self.nodes[q].y >= cpp_min(self.nodes[p].y, self.nodes[r].y)
    }

    /// Check if a polygon diagonal intersects any polygon segment.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let next = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[next].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[next].i != self.nodes[b].i
                && self.intersects(p, next, a, b)
            {
                return true;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }

        false
    }

    /// Check if a polygon diagonal is locally inside the polygon.
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let a_prev = self.nodes[a].prev;
        let a_next = self.nodes[a].next;
        if self.area(a_prev, a, a_next) < 0.0 {
            self.area(a, b, a_next) >= 0.0 && self.area(a, a_prev, b) >= 0.0
        } else {
            self.area(a, b, a_prev) < 0.0 || self.area(a, a_next, b) < 0.0
        }
    }

    /// Check if the middle point of a polygon diagonal is inside the polygon.
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let next = self.nodes[p].next;
            let (pyy, nyy) = (self.nodes[p].y, self.nodes[next].y);
            if ((pyy > py) != (nyy > py))
                && nyy != pyy
                && (px < (self.nodes[next].x - self.nodes[p].x) * (py - pyy) / (nyy - pyy)
                    + self.nodes[p].x)
            {
                inside = !inside;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }

        inside
    }

    /// Link two polygon vertices with a bridge; if the vertices belong to the
    /// same ring, it splits the polygon into two. If one belongs to the outer
    /// ring and another to a hole, it merges it into a single ring.
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let a2 = self.nodes.construct(ai, ax, ay);
        let b2 = self.nodes.construct(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Create a node and optionally link it with a previous one (in a circular
    /// doubly linked list).
    fn insert_node(&mut self, i: usize, x: f64, y: f64, last: usize) -> usize {
        let p = self.nodes.construct(N::truncate(i), x, y);

        if last == NULL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    /// Unlink a node from both the ring and the z-order list.
    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let prev_z = self.nodes[p].prev_z;
        let next_z = self.nodes[p].next_z;
        if prev_z != NULL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NULL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }
}

